        if x == 0:
            return 0

        res = float('inf')
        S = []

        i = 0
        while i < len(nums):
            if i >= x - 1:
                S.append(nums[i - (x - 1)])

            j = bisect.bisect_left(S, nums[i])
            if j < len(S):
