original_code:
class Solution:
    def constructProductMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        m = len(grid[0])
        zero_count = 0
        total = 1
        i = 0

        # First pass: count zeros and calculate product of all non-zero elements
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 0:
                    zero_count += 1
                else:
                    total = (total * grid[i][j]) % 12345

        # Second pass: assign values based on zero count
        for i in range(n):
            for j in range(m):
                if zero_count > 1:
                    grid[i][j] = 0
                elif zero_count == 1:
                    if grid[i][j] == 0:
                        grid[i][j] = total % 12345
                    else:
                        grid[i][j] = (total // grid[i][j]) % 12345
                else:
                    grid[i][j] = total % 12345

        return grid

